/**
 * Типы разбора литералов brick-файла (`src/brick-literals.ts`): язык допустимых
 * значений и разбираемый файл.
 */

/**
 * Значение, допустимое в метаданных brick-файла.
 *
 * Список закрытый и совпадает с тем, что переживает JSON-манифест и Nuxt
 * payload: вычисляемые формы (идентификатор, вызов, шаблон с подстановкой)
 * запрещены — их значение известно только исполнению модуля, а манифест
 * собирается без него.
 */
export type TBrickLiteralValue =
    | string
    | number
    | boolean
    | null
    | TBrickLiteralValue[]
    | { [key: string]: TBrickLiteralValue };

/** Файл, из которого читаются метаданные: путь для диагностики и исходник. */
export interface IBrickSourceFile {
    /** Абсолютный путь brick-файла. */
    filePath: string;
    /** Содержимое файла — по нему считается позиция для сообщения об ошибке. */
    content: string;
}
